    gap: 0.4rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
    font-size: 0.875rem;
}

.review-data dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #eee;
}

.review-work-entry:last-child,
