    border-bottom: none;
}

.review-work-entry p,
.review-reference p {
    margin: 0.2rem 0;
    font-size: 0.875rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    line-height: 1.6;
}

